AND (
    m.receiver_scope = 0
    OR (
        m.receiver_scope = 1
        AND JSON_CONTAINS(m.receiver_values, CAST(#{userId} AS CHAR))
    )

        OR (
            m.receiver_scope = 2
            AND JSON_OVERLAPS(
                m.receiver_values,
                JSON_ARRAY(

                        #{roleId}

                )
            )
        )


        OR (
            m.receiver_scope = 3
            AND JSON_CONTAINS(m.receiver_values, CAST(#{deptId} AS CHAR))
        )

)

mapper.select:
SELECT m.id AS message_id, m.title, m.message_type, m.source_type, m.source_id, m.publish_time, m.create_time, COALESCE(r.read_status, 0) AS read_status, r.read_time FROM sys_message m LEFT JOIN sys_message_receiver r ON r.message_id = m.id AND r.receiver_type = #{receiverType} AND r.receiver_id = #{userId} AND r.is_deleted = 0 WHERE m.is_deleted = 0 AND m.status = 1 AND m.receiver_type = #{receiverType} AND m.channel = 'IN_APP' AND m.publish_time <= NOW() AND (r.id IS NULL OR r.read_status != 2)
AND (r.id IS NULL OR r.read_status = 0)
AND r.read_status = #{readStatus}
AND m.title LIKE CONCAT('%', #{title}, '%')
AND m.message_type = #{messageType}
AND m.publish_time >= #{publishStartDate}
AND m.publish_time < DATE_ADD(#{publishEndDate}, INTERVAL 1 DAY)
ORDER BY m.publish_time DESC, m.id DESC

SELECT m.id FROM sys_message m LEFT JOIN sys_message_receiver r ON r.message_id = m.id AND r.receiver_type = #{receiverType} AND r.receiver_id = #{userId} AND r.is_deleted = 0 WHERE m.is_deleted = 0 AND m.status = 1 AND m.receiver_type = #{receiverType} AND m.channel = 'IN_APP' AND m.publish_time <= NOW() AND (r.id IS NULL OR r.read_status != 2)
AND (r.id IS NULL OR r.read_status = 0)
AND r.read_status = #{readStatus}
